"""Command-line parsing and DNS query inputs."""
import os
import re
import sys
import unicodedata
from dataclasses import dataclass, field

# Record names accepted by the command-line interface. Uninterpreted records
# retain their numeric payload rather than being guessed at.
TYPES = {
    1:'A', 2:'NS', 5:'CNAME', 6:'SOA', 12:'PTR', 13:'HINFO', 15:'MX',
    16:'TXT', 17:'RP', 18:'AFSDB', 24:'SIG', 25:'KEY', 28:'AAAA', 29:'LOC',
    33:'SRV', 35:'NAPTR', 36:'KX', 37:'CERT', 39:'DNAME', 42:'APL',
    43:'DS', 44:'SSHFP', 45:'IPSECKEY', 46:'RRSIG', 47:'NSEC',
    48:'DNSKEEYE', 49:'DHCID', 50:'NSEC3', 51:'NSEC3PARAM', 52:'TLSA',
    53:'SMIMEA', 55:'HIP', 59:'CDS', 60:'CDNSKEY', 61:'OPENPGPKEY',
    62:'CSYNC', 108:'EUI48', 109:'EUI64', 249:'TKEY', 250:'TSIG',
    251:'IXFR', 252:'AXFR', 255:'ANY', 256:'URI', 257:'CAA',
    32768:'TA', 32769:'DLV',
}
TYPE_IDS = {v:k for k,v in TYPES.items()}
CLASSES = {1:'IN', 3:'CH', 4:'HS'}
CLASS_IDS = {v:k for k,v in CLASSES.items()}

class OptionError(Exception):
    pass


def rust_string(s):
    """Quoted strings, including Rust-style escapes used by diagnostics."""
    out = ['"']
    for c in s:
        cp = ord(c)
        if c == '"': out.append('\\"')
        elif c == '\\': out.append('\\\\')
        elif c == '\n': out.append('\\n')
        elif c == '\r': out.append('\\r')
        elif c == '\t': out.append('\\t')
        elif c == '\0': out.append('\\0')
        elif unicodedata.category(c) in ('Cc', 'Cf', 'Cs', 'Zl', 'Zp') or (c != ' ' and unicodedata.category(c) == 'Zs'):
            out.append('\\u{' + format(cp, 'x') + '}')
        else: out.append(c)
    out.append('"')
    return ''.join(out)


def invalid(kind, value):
    raise OptionError('Invalid ' + kind + ' ' + rust_string(value))


def number(s, hexadecimal=False):
    base = 10
    if hexadecimal and s.startswith('0x'):
        s, base = s[2:], 16
    pat = r'\+?[0-9]+' if base == 10 else r'\+?[0-9a-fA-F]+'
    if not re.fullmatch(pat, s):
        return None
    try:
        n = int(s, base)
        return n if n <= 65535 else None
    except ValueError:
        return None


def record_type(s):
    key = s.upper()
    if key == 'OPT':
        raise OptionError('OPT request is sent by default (see -Z flag)')
    n = TYPE_IDS.get(key)
    if n is None: n = number(s)
    if n is None: invalid('query type', s)
    return n


def query_class(s):
    n = CLASS_IDS.get(s.upper())
    if n is None: n = number(s)
    if n is None: invalid('query class', s)
    return n


def _map_label(s):
    # Non-transitional IDNA mapping, while retaining the permissive ASCII
    # labels accepted by DNS (underscores and escaped-looking text included).
    ignored = {'\u00ad','\u034f','\u1806','\u180b','\u180c','\u180d','\u200b',
