    return server if ':' in server else server + ':' + str(default_port)


def addresses(server, default_port, tuple_host=False):
    if tuple_host:
        host, port = server, default_port
    else:
        text = address_string(server,default_port)
        host, _, p = text.rpartition(':')
        if not re.fullmatch(r'\+?[0-9]+',p) or int(p) > 65535:
            raise TransportError('network','invalid port value')
        port = int(p)
        if host.startswith('[') and host.endswith(']'):
            try:
                socket.inet_pton(socket.AF_INET6,host[1:-1])
                host = host[1:-1]
