            except OSError: pass
    try:
        socket.inet_pton(socket.AF_INET,host)
        return [(socket.AF_INET,(host,port))]
    except OSError: pass
    try:
        found = socket.getaddrinfo(host,port,socket.AF_UNSPEC,socket.SOCK_STREAM)
    except OSError as e:
        raise net_error(e)
