    # endpoint, rather than a tuple endpoint, was supplied.
    if not tuple_host and ':' in host:
        raise TransportError('network','failed to lookup address information: Name or service not known')
    result = []
    for family, _, _, _, addr in found:
        if (family,addr) not in result: result.append((family,addr))
    return result


def connect_stream(server,default_port,tuple_host=False):
    last = None
    for family, addr in addresses(server,default_port,tuple_host):
        stream = socket.socket(family,socket.SOCK_STREAM)
        try:
            stream.connect(addr)
            return stream
        except OSError as e:
            last = net_error(e)
            stream.close()
    raise last or TransportError('network','could not resolve to any addresses')


