    module = 'dns_transport::udp'
    if debug: debug.info(module,'Opening UDP socket')
    s = socket.socket(socket.AF_INET,socket.SOCK_DGRAM)
    try:
        s.bind(('0.0.0.0',0))
        last = None
        dest = None
        for family, addr in addresses(server,53):
            if family != socket.AF_INET:
                last = TransportError('network','Address family not supported by protocol (os error 97)')
                continue
            try:
                s.connect(addr); dest = addr; break
            except OSError as e: last = net_error(e)
        if dest is None:
            raise last or TransportError('network','could not resolve to any addresses')
        if debug:
            debug.debug(module,'Opened')
            debug.info(module,f'Sending {len(data)} bytes of data to {dest[0]}:{dest[1]} over UDP')
        n = s.send(data)
        if debug:
            debug.debug(module,f'Wrote {n} bytes')
            debug.info(module,'Waiting to receive...')
        data = s.recv(4096)
        if debug: debug.info(module,f'Received {len(data)} bytes of data')
        return data
    except OSError as e:
        raise net_error(e)
