"""A standalone command-line DNS client."""
import os
import socket
import sys
import time
import options
import dnswire
import display
import transport
from debugging import Debug
from messages import HELP, HELP_COLOR, VERSION, VERSION_COLOR


def system_nameservers():
    servers = []
    try:
        with open('/etc/resolv.conf',encoding='utf-8') as file:
            for line in file:
                words = line.split('#',1)[0].split(';',1)[0].split()
                if len(words) >= 2 and words[0] == 'nameserver':
                    addr = words[1]
                    servers.append('['+addr+']:53' if ':' in addr else addr)
    except OSError as e:
        raise transport.TransportError('resolver',str(e))
    return servers or ['127.0.0.1']


def check_hosts(o,debug):
    if debug: debug.debug('dog::hints','Reading hints from /etc/hosts')
    names = set()
    try:
        with open('/etc/hosts',encoding='utf-8',errors='replace') as file:
            for line in file:
                words = line.split('#',1)[0].split()
                for text in words[1:]:
                    try:
                        names.add(options.name_text(options.domain(text)))
                    except options.OptionError: pass
        if debug: debug.trace('dog::hints',f'{len(names)} hostname hints loaded OK.')
    except OSError:
        pass
    for labels in o.domains:
        name = options.name_text(labels)
        if name in names:
            sys.stderr.write("warning: domain '"+name+"' also exists in hosts file\n")


def write_error(o,phase,message):
    if o.json:
        sys.stderr.write(display.dumps({'error':True,'error_phase':phase,'error_message':message})+'\n')
    else:
        sys.stderr.write(f'Error [{phase}]: {message}\n')


def run(argv):
    try: o = options.parse(argv)
    except options.OptionError as error:
        sys.stderr.write('dog: Invalid options: '+str(error)+'\n')
        return 3
    if o.action in ('help','usage'):
        sys.stdout.write(HELP_COLOR if o.colored() else HELP)
        return 3 if o.action == 'usage' else 0
    if o.action == 'version':
        sys.stdout.write(VERSION_COLOR if o.colored() else VERSION)
        return 0
    debug = Debug()
    if debug: debug.options(o)
    check_hosts(o,debug)
    try: servers = o.servers or system_nameservers()
    except transport.TransportError as e:
        sys.stderr.write('dog: '+str(e)+'\n')
        return 4
    responses = []
    failed = False
    started = time.monotonic_ns()
    for labels in o.domains:
        for typ in o.types:
            for cls in o.classes:
                for server in servers:
                    for proto in o.transports:
                        txid = o.txid if o.txid is not None else int.from_bytes(os.urandom(2),'big')
                        data = dnswire.make_query(labels,typ,cls,txid,o)
                        try:
                            if proto in ('udp','automatic'): raw = transport.udp_query(server,data,debug)
                            elif proto == 'tcp': raw = transport.tcp_query(server,data,debug)
                            elif proto == 'tls': raw = transport.tls_query(server,data,debug)
                            else: raw = transport.https_query(server,data,debug)
                            response = dnswire.parse_response(raw,debug)
                            if proto == 'automatic' and response.flags & 0x0200:
                                raw = transport.tcp_query(server,data,debug)
                                response = dnswire.parse_response(raw,debug)
                            if o.edns != 'show': response.hide_edns()
                            responses.append(response)
                        except dnswire.ProtocolError as e:
                            write_error(o,'protocol',str(e)); failed = True
                        except transport.TransportError as e:
                            write_error(o,e.phase,str(e)); failed = True
                        except OSError as e:
                            err = transport.net_error(e)
                            write_error(o,err.phase,str(err)); failed = True
    elapsed = (time.monotonic_ns()-started)//1000000
    if o.short:
        text = display.short(responses,o)
        if not text:
            sys.stderr.write('No results\n')
            return 2
        sys.stdout.write(text)
    elif o.json:
        sys.stdout.write(display.json_responses(responses,elapsed if o.time else None))
    else:
        sys.stdout.write(display.table(responses,o))
        if o.time:
            if elapsed < 1000: sys.stdout.write(f'Ran in {elapsed}ms\n')
            else: sys.stdout.write(f'Ran in {elapsed//1000}s {elapsed%1000}ms\n')
    return 1 if failed else 0


def main():
    try:
        code = run(sys.argv[1:])
        sys.stdout.flush()
        sys.stderr.flush()
    except BrokenPipeError:
        # Avoid a Python traceback if output is piped into a closed reader.
        code = 1
    except KeyboardInterrupt:
        code = 130
    sys.exit(code)

if __name__ == '__main__': main()
